// =====================================================
// 🔍 AUDITORÍA DE PEDIDOS HISTÓRICOS v1.0
// =====================================================
// Compara TODOS los pedidos existentes contra el catálogo actual
// Genera reporte de discrepancias de precios
// =====================================================

// Obtener datos de ambas fuentes
const allItems = $input.all();

// Separar pedidos y productos (vienen mezclados del merge)
let pedidos = [];
let productos = [];

allItems.forEach(item => {
  if (item.json.order_data || item.json.guest_name) {
    pedidos.push(item.json);
  } else if (item.json.name && item.json.price !== undefined) {
    productos.push(item.json);
  }
});

// Si no hay separación clara, intentar de otra forma
if (pedidos.length === 0 || productos.length === 0) {
  // Asumir que el primer input tiene pedidos
  const input1 = $('📦 Obtener Todos los Pedidos').all();
  const input2 = $('💰 Obtener Catálogo Actual').all();

  pedidos = input1.map(i => i.json);
  productos = input2.map(i => i.json);
}

// Crear mapa de precios actuales (ID -> Precio)
const preciosActuales = {};
productos.forEach(p => {
  preciosActuales[p.id] = {
    nombre: p.name,
    precio: parseFloat(p.price) || 0
  };
});

// Estadísticas globales
let totalPedidosAnalizados = 0;
let pedidosConDiscrepancias = 0;
let totalDiscrepancias = 0;
let montoTotalDiferencia = 0;

const reporteDetallado = [];
const resumenDiscrepancias = [];

pedidos.forEach(pedido => {
  totalPedidosAnalizados++;

  // Parsear order_data
  let orderData;
  try {
    orderData = typeof pedido.order_data === 'string' 
      ? JSON.parse(pedido.order_data) 
      : pedido.order_data;
  } catch (e) {
    return; // Skip invalid orders
  }

  if (!orderData || !orderData.items || !Array.isArray(orderData.items)) {
    return;
  }

  const discrepanciasPedido = [];
  let diferenciaTotal = 0;

  orderData.items.forEach(item => {
    const productoId = item.product_id || item.id;
    const precioEnPedido = parseFloat(item.unit_price || item.precio) || 0;
    const cantidad = parseInt(item.quantity || item.cantidad) || 1;

    const productoActual = preciosActuales[productoId];

    if (productoActual && productoActual.precio !== precioEnPedido) {
      totalDiscrepancias++;
      const diferencia = (productoActual.precio - precioEnPedido) * cantidad;
      diferenciaTotal += diferencia;

      discrepanciasPedido.push({
        producto: item.product_name || productoActual.nombre,
        precio_pedido: precioEnPedido,
        precio_actual: productoActual.precio,
        cantidad: cantidad,
        diferencia: diferencia
      });
    }
  });

  if (discrepanciasPedido.length > 0) {
    pedidosConDiscrepancias++;
    montoTotalDiferencia += diferenciaTotal;

    resumenDiscrepancias.push({
      order_id: pedido.id?.substring(0, 8) || 'N/A',
      cliente: pedido.guest_name || 'Desconocido',
      telefono: pedido.guest_phone || 'N/A',
      fecha: pedido.created_at ? new Date(pedido.created_at).toLocaleDateString('es-CO') : 'N/A',
      total_pedido: pedido.total_amount,
      discrepancias: discrepanciasPedido,
      diferencia_total: diferenciaTotal
    });
  }
});

// Generar mensaje de reporte para WhatsApp
let mensaje = `📊 *AUDITORÍA DE PEDIDOS*\n`;
mensaje += `Fecha: ${new Date().toLocaleDateString('es-CO')}\n\n`;
mensaje += `📈 *RESUMEN:*\n`;
mensaje += `• Pedidos analizados: ${totalPedidosAnalizados}\n`;
mensaje += `• Con discrepancias: ${pedidosConDiscrepancias}\n`;
mensaje += `• Total discrepancias: ${totalDiscrepancias}\n`;
mensaje += `• Diferencia total: $${montoTotalDiferencia.toLocaleString('es-CO')}\n\n`;

if (pedidosConDiscrepancias === 0) {
  mensaje += `✅ *¡Todos los pedidos tienen precios correctos!*`;
} else {
  mensaje += `⚠️ *PEDIDOS CON PROBLEMAS:*\n`;
  resumenDiscrepancias.slice(0, 5).forEach((p, i) => {
    mensaje += `\n${i+1}. ID: ${p.order_id} (${p.cliente})\n`;
    mensaje += `   Diferencia: $${p.diferencia_total.toLocaleString('es-CO')}\n`;
  });

  if (resumenDiscrepancias.length > 5) {
    mensaje += `\n... y ${resumenDiscrepancias.length - 5} pedidos más.`;
  }
}

return [{
  json: {
    resumen: {
      total_pedidos: totalPedidosAnalizados,
      con_discrepancias: pedidosConDiscrepancias,
      total_discrepancias: totalDiscrepancias,
      monto_diferencia: montoTotalDiferencia
    },
    detalle: resumenDiscrepancias,
    mensaje_whatsapp: mensaje
  }
}];
